package kernel

import (
	"errors"
	"math"
	"testing"
	"time"
)

// Spec 3.4: IDs are UUIDv7, generated by the application.
func TestUUIDv7GeneratorIsTimeOrdered(t *testing.T) {
	g := UUIDv7Generator{}
	a, b := g.NewID(), g.NewID()
	if a == b || a.IsZero() {
		t.Fatalf("ids must be unique and non-zero: %s %s", a, b)
	}
	if a.String()[14] != '7' {
		t.Fatalf("want version 7 uuid, got %s", a)
	}
	p, err := ParseID(a.String())
	if err != nil || p != a {
		t.Fatalf("round trip: %v %s", err, p)
	}
	if _, err := ParseID("nope"); err == nil {
		t.Fatal("want error for invalid id")
	}
}

// Spec 3.2: Float rejects NaN and Infinity.
func TestFloatRejectsNaNAndInf(t *testing.T) {
	for _, f := range []float64{math.NaN(), math.Inf(1), math.Inf(-1)} {
		if _, ok := NewFloat(f); ok {
			t.Fatalf("NewFloat(%v) accepted", f)
		}
	}
}

// Spec 3.2: Decimal is exact.
func TestDecimalExact(t *testing.T) {
	a, b := MustDecimal("0.1"), MustDecimal("0.2")
	s, err := a.Add(b)
	if err != nil || s.String() != "0.3" {
		t.Fatalf("0.1+0.2 = %s, %v", s, err)
	}
	if _, err := a.Quo(DecimalFromInt64(0)); err == nil {
		t.Fatal("want division by zero error")
	}
	if _, err := ParseDecimal("NaN"); err == nil {
		t.Fatal("NaN decimal accepted")
	}
}

func TestEqualAndCompare(t *testing.T) {
	now := time.Now()
	cases := []struct {
		a, b Value
		eq   bool
		cmp  int
	}{
		{String("a"), String("b"), false, -1},
		{Enum("x"), String("x"), true, 0},
		{Int64(3), Int64(3), true, 0},
		{Int64(2), Float(2.5), false, -1},
		{DecimalValue{MustDecimal("1.50")}, DecimalValue{MustDecimal("1.5")}, true, 0},
		{NewTime(now), NewTime(now.Add(time.Second)), false, -1},
		{Null{}, String("a"), false, -1},
	}
	for _, c := range cases {
		if got := Equal(c.a, c.b); got != c.eq {
			t.Errorf("Equal(%v,%v)=%v", c.a, c.b, got)
		}
		got, ok := Compare(c.a, c.b)
		if !ok || got != c.cmp {
			t.Errorf("Compare(%v,%v)=%d,%v want %d", c.a, c.b, got, ok, c.cmp)
		}
	}
	o1 := NewObject([]string{"a"}, map[string]Value{"a": List{Elem: KindInt64, Items: []Value{Int64(1)}}})
	o2 := NewObject([]string{"a"}, map[string]Value{"a": List{Elem: KindInt64, Items: []Value{Int64(1)}}})
	if !Equal(o1, o2) {
		t.Error("objects should be equal")
	}
}

func TestNative(t *testing.T) {
	id := UUIDv7Generator{}.NewID()
	o := NewObject([]string{"r", "n"}, map[string]Value{"r": Ref{ID: id}, "n": Null{}})
	m := Native(o).(map[string]any)
	if m["r"] != id.String() || m["n"] != nil {
		t.Fatalf("native = %#v", m)
	}
}

func TestErrorCodes(t *testing.T) {
	vc := &VersionConflictError{Conflicts: []VersionConflict{{Current: 3}}}
	if !errors.Is(vc, ErrVersionConflict) || CodeOf(vc) != CodeVersionConflict {
		t.Fatal("version conflict code")
	}
	ve := NewValidationError(FieldError{Path: "/a", Code: "type"})
	if !errors.Is(ve, ErrValidation) || CodeOf(ve) != CodeValidationFailed {
		t.Fatal("validation code")
	}
	if CodeOf(errors.New("x")) != CodeInternal {
		t.Fatal("internal code")
	}
	if !errors.Is(NewError(CodeNotFound, "x"), ErrNotFound) {
		t.Fatal("not found")
	}
}
